export const assets={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#283f32\"><meta name=\"description\" content=\"A small packing list for a day outside. Works offline after the first visit.\"><title>Fieldkit · A day outside</title><link rel=\"icon\" href=\"/icon.svg\" type=\"image/svg+xml\"><link rel=\"manifest\" href=\"/manifest.webmanifest\"><link rel=\"stylesheet\" href=\"/styles.css\"><script src=\"/version.js\" defer></script><script src=\"/app.js\" defer></script></head>\n<body><header><a class=\"brand\" href=\"/\">fieldkit<span>A LITTLE LESS TO REMEMBER</span></a><div class=\"status\"><span id=\"connection\">Checking connection</span><span id=\"offline-ready\">Preparing offline access</span></div></header>\n<main><section class=\"intro\"><div><p class=\"eyebrow\">THE EVERYDAY ESCAPE / NO. 01</p><h1>A day outside.<br>A little more ready.</h1><p class=\"lede\">The useful things, all in one place. Pack a small bag and leave room for whatever you find.</p></div><div class=\"bag\" aria-hidden=\"true\"><div class=\"handle\"></div><div class=\"bag-body\"><span>FK</span><div class=\"pocket\"></div></div><i class=\"leaf\"></i></div></section>\n<section class=\"workspace\" aria-labelledby=\"list-title\"><div class=\"list-panel\"><div class=\"section-title\"><div><p class=\"eyebrow\">YOUR BAG</p><h2 id=\"list-title\">A good starting point.</h2></div><button class=\"quiet\" id=\"export\">Export list</button></div><div class=\"filters\" aria-label=\"Filter items\"><button data-filter=\"all\" aria-pressed=\"true\">Everything</button><button data-filter=\"remaining\" aria-pressed=\"false\">To pack</button><button data-filter=\"packed\" aria-pressed=\"false\">Packed</button></div><ul id=\"items\" aria-label=\"Packing list\"></ul><p id=\"empty\" hidden>Nothing in this view. A little breathing room.</p><p id=\"message\" role=\"status\" aria-live=\"polite\"></p></div>\n<aside><div class=\"summary\"><p class=\"eyebrow\">MAKING ROOM</p><p id=\"count\" class=\"count\">—</p><p>things packed</p><progress id=\"progress\" value=\"0\" max=\"6\" aria-label=\"Packing progress\"></progress><dl><div><dt>In your bag</dt><dd id=\"packed-weight\">—</dd></div><div><dt>Everything on the list</dt><dd id=\"total-weight\">—</dd></div></dl><p class=\"tip\" id=\"tip\"></p></div><form id=\"add-form\"><h3>Make it yours.</h3><label for=\"item-label\">One more useful thing</label><input id=\"item-label\" name=\"label\" maxlength=\"60\" required placeholder=\"A sketchbook, perhaps\"><label for=\"item-weight\">Weight in grams</label><div class=\"add-row\"><input id=\"item-weight\" name=\"weight\" type=\"number\" min=\"1\" max=\"20000\" step=\"1\" value=\"100\" required><button class=\"primary\" type=\"submit\">Add item</button></div><small>Up to 30 items. Estimates are fine.</small></form></aside></section>\n<section class=\"note\"><span class=\"note-mark\" aria-hidden=\"true\">↗</span><div><h3>Your list comes with you.</h3><p>After the first visit, this page works without a connection. Your list stays in this browser; export a copy if you want to keep it elsewhere.</p></div><button id=\"reset\" class=\"quiet\">Restore sample list</button></section><section class=\"updates\"><span id=\"release\"></span><button class=\"quiet\" id=\"check-update\">Check for updates</button><button class=\"primary\" id=\"apply-update\" hidden>Use new version</button><span id=\"update-status\" role=\"status\"></span></section></main>\n<footer><span>Fieldkit / a small plan for a good day.</span><span>Synthetic demo · No account or sync</span></footer></body></html>\n"},"/styles.css":{"type":"text/css; charset=utf-8","body":":root{font-family:Arial,sans-serif;color:#283f32;background:#f4f2e9;font-synthesis:none}*{box-sizing:border-box}body{margin:0}button,input{font:inherit}button{cursor:pointer}button:disabled{cursor:wait;opacity:.55}a{color:inherit}header,main,footer{max-width:1180px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;padding:32px 0;border-bottom:1px solid #c9d0c3}.brand{text-decoration:none;font:700 38px Georgia,serif;letter-spacing:-2px}.brand span{display:block;font:9px Arial,sans-serif;letter-spacing:2px;margin-top:6px}.status{font-size:12px;display:flex;gap:18px}.status span:first-child:before{content:\"\";display:inline-block;background:#788754;width:7px;height:7px;border-radius:50%;margin-right:7px}.intro{display:grid;grid-template-columns:1.5fr 1fr;align-items:center;gap:60px;padding:66px 0 54px}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:700}h1{font:normal clamp(42px,5.5vw,68px)/1.05 Georgia,serif;letter-spacing:-2px;margin:22px 0}.lede{max-width:430px;font-size:15px;line-height:1.7;color:#617065}.bag{height:270px;position:relative;display:flex;justify-content:center;align-items:flex-end}.handle{position:absolute;top:9px;width:102px;height:90px;border:16px solid #897e54;border-radius:42px 42px 0 0}.bag-body{width:210px;height:215px;background:#b8b18b;border-radius:9px 9px 34px 34px;transform:rotate(-6deg);position:relative;box-shadow:14px 15px 0 #e4e1d1}.bag-body span{position:absolute;top:28px;left:80px;font:24px Georgia,serif;opacity:.7}.pocket{position:absolute;width:128px;height:92px;bottom:24px;left:41px;border:1px solid #8b896b;border-radius:2px 2px 23px 23px}.pocket:before{content:\"\";position:absolute;width:106px;left:10px;top:14px;border-top:2px solid #8b896b}.leaf{position:absolute;width:40px;height:110px;background:#768859;border-radius:0 100% 0 100%;transform:rotate(24deg);right:60px;bottom:12px}.workspace{display:grid;grid-template-columns:1.8fr 1fr;gap:58px;border-top:1px solid #c9d0c3;padding-top:35px}.section-title{display:flex;justify-content:space-between;align-items:center;gap:16px}h2{font:normal 29px Georgia,serif;margin:10px 0 20px}h3{font:normal 23px Georgia,serif;margin:0 0 14px}.quiet{background:transparent;border:1px solid #bac3b5;border-radius:4px;padding:9px 12px;color:#283f32;font-size:12px}.filters{display:flex;gap:8px;margin:8px 0 18px}.filters button{border:0;background:transparent;padding:8px 13px;color:#52634f;border-radius:20px;font-size:12px}.filters button[aria-pressed=true]{background:#283f32;color:#fff}ul{list-style:none;margin:0;padding:0}.item{display:grid;grid-template-columns:28px 1fr auto auto;align-items:center;gap:14px;min-height:75px;border-top:1px solid #d9ddcf}.item label{display:flex;gap:14px;align-items:center;grid-column:1/3;cursor:pointer;overflow-wrap:anywhere}.item input{accent-color:#526c48;width:19px;height:19px;flex:none}.item .weight{font-size:12px;color:#6a7869;white-space:nowrap}.item[data-packed=true] .name{text-decoration:line-through;color:#7a8575}.remove{border:0;background:transparent;color:#8b927f;font-size:20px;padding:8px}.summary{background:#e4e7d7;padding:27px;border-radius:4px}.count{font:normal 52px Georgia,serif;margin:15px 0 0}.count+p{font-size:12px;margin-top:7px}progress{accent-color:#526c48;height:7px;width:100%;margin:12px 0}dl{font-size:12px}dl div{display:flex;justify-content:space-between;padding:9px 0}dd{margin:0;font-weight:bold}.tip{font:italic 16px/1.5 Georgia,serif;border-top:1px solid #c5cdb9;padding-top:18px}form{margin:27px 0}form label{display:block;font-size:12px;margin:15px 0 7px}input:not([type=checkbox]){width:100%;border:1px solid #bcc4b5;background:#fbfaf5;color:#283f32;border-radius:3px;padding:11px}.add-row{display:flex;gap:8px}.add-row input{min-width:0;flex:1}.primary{background:#283f32;color:#fff;border:0;border-radius:3px;padding:10px 16px;font-size:12px;white-space:nowrap}small{display:block;font-size:11px;color:#75816e;margin-top:12px}.note{margin-top:45px;padding:30px 0;border-top:1px solid #c9d0c3;border-bottom:1px solid #c9d0c3;display:flex;align-items:center;gap:26px}.note-mark{font:50px Georgia,serif}.note div{flex:1}.note h3{font-size:22px;margin-bottom:8px}.note p{font-size:12px;line-height:1.7;max-width:600px;margin:0;color:#637160}.updates{display:flex;align-items:center;gap:15px;font-size:11px;padding:23px 0;flex-wrap:wrap}footer{display:flex;justify-content:space-between;padding:24px 0 35px;font-size:11px;color:#6b7867}#message,#empty{font-size:12px;line-height:1.5}button:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #9c884e;outline-offset:3px}[hidden]{display:none!important}@media(max-width:1250px){header,main,footer{margin-left:35px;margin-right:35px}}@media(max-width:700px){header,main,footer{margin-left:20px;margin-right:20px}header{padding:23px 0}.brand{font-size:32px}.brand span{font-size:7px}.status{flex-direction:column;gap:6px;font-size:10px;text-align:right}.intro{grid-template-columns:1fr;gap:8px;padding:36px 0}.intro .bag{display:none}h1{font-size:46px}.workspace{grid-template-columns:1fr;gap:30px;padding-top:23px}h2{font-size:25px}.section-title{gap:9px}.section-title .quiet{font-size:10px}.item{gap:9px}.summary{padding:24px}.note{margin-top:12px;align-items:flex-start;gap:14px;flex-wrap:wrap}.note div{flex-basis:75%}.note .quiet{margin-left:42px}footer{gap:20px;line-height:1.6;align-items:flex-start}.updates{gap:9px}}\n"},"/version.js":{"type":"text/javascript; charset=utf-8","body":"window.FIELDKIT={release:1,tip:'Start with the essentials. A lighter bag leaves more room for the day.'};\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst $=s=>document.querySelector(s), config=window.FIELDKIT;\nconst seed=[['notebook','Notebook',220],['water','Water bottle',750],['jacket','Rain jacket',320],['camera','Small camera',540],['snack','Something to share',180],['map','Paper map',45]].map(([id,label,weight])=>({id,label,weight,packed:false}));\nlet db,filter='all',registration,refresh=0;\nconst channel='BroadcastChannel' in window?new BroadcastChannel('fieldkit-changes'):null;\nconst grams=n=>n>=1000?(n/1000).toFixed(2)+' kg':n+' g';\nfunction message(text){$('#message').textContent=text}\nfunction openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('fieldkit',1);req.onupgradeneeded=()=>{const store=req.result.createObjectStore('items',{keyPath:'id'});seed.forEach(item=>store.put(item))};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}\nfunction all(){return new Promise((resolve,reject)=>{const req=db.transaction('items').objectStore('items').getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}\nfunction change(action){return new Promise((resolve,reject)=>{const tx=db.transaction('items','readwrite');action(tx.objectStore('items'));tx.oncomplete=()=>{channel?.postMessage('changed');resolve()};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Change was not saved'))})}\nasync function render(){const serial=++refresh,items=await all();if(serial!==refresh)return;items.sort((a,b)=>a.label.localeCompare(b.label));const packed=items.filter(x=>x.packed);$('#count').textContent=packed.length+' / '+items.length;$('#progress').value=packed.length;$('#progress').max=items.length||1;$('#packed-weight').textContent=grams(packed.reduce((s,x)=>s+x.weight,0));$('#total-weight').textContent=grams(items.reduce((s,x)=>s+x.weight,0));const shown=items.filter(x=>filter==='all'||x.packed===(filter==='packed'));$('#items').replaceChildren();for(const item of shown){const li=document.createElement('li');li.className='item';li.dataset.id=item.id;li.dataset.packed=item.packed;const label=document.createElement('label'),box=document.createElement('input'),name=document.createElement('span'),weight=document.createElement('span'),remove=document.createElement('button');box.type='checkbox';box.checked=item.packed;box.setAttribute('aria-label','Pack '+item.label);name.className='name';name.textContent=item.label;weight.className='weight';weight.textContent=grams(item.weight);remove.className='remove';remove.textContent='×';remove.setAttribute('aria-label','Remove '+item.label);box.onchange=()=>act(async()=>{await change(store=>{const req=store.get(item.id);req.onsuccess=()=>{if(req.result)store.put({...req.result,packed:box.checked})}});message(item.label+(box.checked?' packed.':' moved back to the list.'))});remove.onclick=()=>act(async()=>{await change(store=>store.delete(item.id));message(item.label+' removed.')});label.append(box,name);li.append(label,weight,remove);$('#items').append(li)}$('#empty').hidden=shown.length>0;document.body.dataset.ready='true'}\nasync function act(task){try{await task();await render()}catch(error){message('Could not save: '+error.message)}}\nfunction connectivity(){$('#connection').textContent=navigator.onLine?'Connected':'Offline';document.body.dataset.online=String(navigator.onLine)}\nasync function offline(){if(!('serviceWorker' in navigator)){$('#offline-ready').textContent='Offline access unavailable';return}try{registration=await navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'});await navigator.serviceWorker.ready;$('#offline-ready').textContent='Ready to use offline';document.body.dataset.offlineReady='true';const waiting=()=>{$('#apply-update').hidden=!registration.waiting;if(registration.waiting)$('#update-status').textContent='An update is ready. Your list will stay.'};registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',waiting)});waiting();let reloading=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!reloading){reloading=true;location.reload()}})}catch(error){$('#offline-ready').textContent='Offline setup needs another visit';$('#update-status').textContent=error.message}}\n$('#release').textContent='Fieldkit / release '+config.release;$('#tip').textContent=config.tip;document.body.dataset.release=String(config.release);\nfor(const button of document.querySelectorAll('[data-filter]'))button.onclick=()=>{filter=button.dataset.filter;for(const b of document.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',String(b===button));render().catch(e=>message(e.message))};\n$('#add-form').onsubmit=event=>{event.preventDefault();const label=$('#item-label').value.trim(),weight=Number($('#item-weight').value);if(!label||label.length>60||!Number.isInteger(weight)||weight<1||weight>20000){message('Use a name and a whole-number weight from 1 to 20,000 grams.');return}act(async()=>{let full=false;await change(store=>{const req=store.count();req.onsuccess=()=>{if(req.result>=30){full=true;return}store.put({id:crypto.randomUUID(),label,weight,packed:false})}});if(full){message('There is room for 30 items. Remove one to make space.');return}$('#item-label').value='';message(label+' added.')})};\n$('#reset').onclick=()=>act(async()=>{await change(store=>{store.clear();seed.forEach(item=>store.put(item))});message('Sample list restored.')});\n$('#export').onclick=async()=>{try{const blob=new Blob([JSON.stringify({format:'fieldkit.v1',items:await all()},null,2)+'\\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldkit-list.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('List exported.')}catch(e){message('Export failed: '+e.message)}};\n$('#check-update').onclick=async()=>{if(!registration)return;$('#update-status').textContent='Checking…';try{await registration.update();$('#update-status').textContent=registration.waiting?'An update is ready. Your list will stay.':'Update check complete.'}catch{$('#update-status').textContent='Reconnect to check for updates.'}};\n$('#apply-update').onclick=()=>registration?.waiting?.postMessage({type:'ACTIVATE'});\nwindow.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);channel?.addEventListener('message',()=>{if(db)render().catch(e=>message(e.message))});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&db)render().catch(e=>message(e.message))});\nconnectivity();openDB().then(async value=>{db=value;await render();await offline()}).catch(e=>message('Browser storage unavailable: '+e.message));\n"},"/manifest.webmanifest":{"type":"application/manifest+json; charset=utf-8","body":"{\"name\":\"Fieldkit — a day outside\",\"short_name\":\"Fieldkit\",\"id\":\"/\",\"start_url\":\"/\",\"scope\":\"/\",\"display\":\"standalone\",\"background_color\":\"#f4f2e9\",\"theme_color\":\"#283f32\",\"icons\":[{\"src\":\"/icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any\"}]}\n"},"/icon.svg":{"type":"image/svg+xml","body":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"192\" height=\"192\" viewBox=\"0 0 192 192\"><rect width=\"192\" height=\"192\" rx=\"38\" fill=\"#283f32\"/><path d=\"M72 65V52a24 24 0 0 1 48 0v13\" fill=\"none\" stroke=\"#b8b18b\" stroke-width=\"10\"/><path d=\"M48 62h96v80a18 18 0 0 1-18 18H66a18 18 0 0 1-18-18Z\" fill=\"#b8b18b\"/><path d=\"M69 104h54v28a12 12 0 0 1-12 12H81a12 12 0 0 1-12-12Z\" fill=\"none\" stroke=\"#283f32\" stroke-width=\"3\"/></svg>\n"},"/sw.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst RELEASE=1,CACHE='fieldkit-shell-v'+RELEASE;\nconst SHELL=['/','/index.html','/styles.css','/version.js','/app.js','/manifest.webmanifest','/icon.svg'];\nself.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL))));\nself.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('fieldkit-shell-v')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));\nself.addEventListener('message',event=>{if(event.data?.type==='ACTIVATE')self.skipWaiting()});\nself.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!SHELL.includes(url.pathname))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);return await cache.match(url.pathname)||fetch(event.request)})())});\n"}};
